'use client';
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useTween } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Fold, Swap, useGrow } from '../lib/motion';
import { useHoverGlide } from '../lib/glide';
import '../designme.css';
import './score-breakdown.css';

export interface ScoreFactor {
  key: string;
  /** Like "Speed" */
  label: string;
  /** The points it can earn; the weights add up to 100 */
  weight: number;
  /** The points it earned */
  earned: number;
  /** The agent's one-line note, like "Median reply 6.4s, target under 4s" */
  note: string;
  /** Adds an Improve button to the open row */
  improvable?: boolean;
  /** A line shown first in the open row, like what was changed */
  detail?: string;
}

export interface ScoreProposal {
  /** What the agent would change */
  text: ReactNode;
  /** What it would gain, like "About 2.1s faster a reply" */
  gain?: string;
  /** The points the factor would earn after it */
  to: number;
}

export interface ScoreBreakdownProps {
  factors: ScoreFactor[];
  title?: string;
  /** Last period's score, for the change beside the band word */
  previous?: number;
  /** What the change is measured against ("since last week") */
  since?: string;
  /** The open rows, by key */
  open?: string[];
  defaultOpen?: string[];
  onOpenChange?: (open: string[]) => void;
  /** Called by Improve. Return the agent's proposal (or a promise of it); while it waits the row says the agent is looking */
  onImprove?: (factor: ScoreFactor) => ScoreProposal | Promise<ScoreProposal>;
  /** Called by Apply on a proposal; update the factor's `earned` and `note` */
  onApply?: (factor: ScoreFactor, proposal: ScoreProposal) => void;
  /** What the row says while the agent works on a proposal */
  improvingLabel?: string;
  className?: string;
}

const PAL = ['var(--dm-c1)', 'var(--dm-c2)', 'var(--dm-c3)', 'var(--dm-c4)', 'var(--dm-c5)', 'var(--dm-c6)'];
const band = (s: number) => s >= 90 ? 'Excellent' : s >= 75 ? 'Good' : s >= 60 ? 'Fair' : 'Needs work';
const CX = 100, CY = 100, RAD = 86, GAP = .04;
const at = (a: number) => [CX + Math.cos(a) * RAD, CY + Math.sin(a) * RAD];
const arc = (a0: number, a1: number) => { const [x0, y0] = at(a0), [x1, y1] = at(a1); return `M${x0.toFixed(2)} ${y0.toFixed(2)}A${RAD} ${RAD} 0 0 1 ${x1.toFixed(2)} ${y1.toFixed(2)}`; };

function Segment({ a0, a1, share, color, on, onPoint }: { a0: number; a1: number; share: number; color: string; on: boolean; onPoint: (on: boolean) => void }) {
  const p = useTween(share, 900, 0);
  return (
    <g className={cx(on && 'dm-on')} onPointerEnter={e => { if (e.pointerType !== 'touch') onPoint(true); }} onPointerLeave={() => onPoint(false)}>
      <path className="dm-tr" d={arc(a0, a1)} />
      {p > 0 && <path className="dm-fl" style={{ stroke: color }} d={arc(a0, a0 + (a1 - a0) * Math.min(1, p))} />}
    </g>
  );
}

/** An open row's detail: it eases to its new height when what it says changes (the agent looking, its proposal, the result) */
function Detail({ children }: { children: ReactNode }) {
  const [box, inner] = useGrow();
  return <div ref={box} className="dm-sbx-d dm-growing"><div ref={inner} className="dm-grow">{children}</div></div>;
}

/** A score out of 100 whose gauge is split by what goes into it, each part filled by the points it earned, with the weakest flagged and an agent's fix one click away. */
export function ScoreBreakdown({ factors, title = 'Quality score', previous, since = 'since last week', open, defaultOpen = [], onOpenChange, onImprove, onApply, improvingLabel = 'Looking into it', className }: ScoreBreakdownProps) {
  const [opened, setOpened] = useControllable(open, defaultOpen, onOpenChange);
  const [hot, setHot] = useState(-1);
  const [drawn, setDrawn] = useState(false);
  const [props, setProps] = useState<Record<string, ScoreProposal | 'busy'>>({});
  useEffect(() => { const t = setTimeout(() => setDrawn(true), 280); return () => clearTimeout(t); }, []);
  const total = factors.reduce((t, f) => t + f.earned, 0);
  const shown = useTween(drawn ? total : 0, 1000, 0);
  const weakest = factors.reduce((m, f, i) => f.earned / f.weight < factors[m].earned / factors[m].weight ? i : m, 0);
  // a style with round ends (--dm-sbx-cap: Soft's) draws each part that much shorter at both ends, so the caps keep the gaps
  const gauge = useRef<HTMLDivElement>(null), [cap, setCap] = useState(0);
  useEffect(() => { if (gauge.current) setCap((parseFloat(getComputedStyle(gauge.current).getPropertyValue('--dm-sbx-cap')) || 0) / RAD); }, []);
  // Clean's one hover: a highlight that glides from factor to factor; the lit and the open one keep their own
  const listRef = useRef<HTMLDivElement>(null);
  useHoverGlide(listRef, '.dm-sbx-r', { hl: '.dm-on', keep: '.dm-open' });
  let a = Math.PI;
  const seg = factors.map(f => { const span = f.weight / 100 * Math.PI, s = [a + GAP / 2 + cap, a + span - GAP / 2 - cap]; a += span; return s; });
  const d = previous === undefined ? null : total - previous;
  const improve = async (f: ScoreFactor) => {
    if (!onImprove) return;
    setProps(p => ({ ...p, [f.key]: 'busy' }));
    const pr = await onImprove(f); setProps(p => ({ ...p, [f.key]: pr }));
  };
  const drop = (k: string) => setProps(p => { const n = { ...p }; delete n[k]; return n; });
  return (
    <div data-dm="" className={cx('dm-sbx dm-panel', className)}>
      <div className="dm-sbx-top">
        <div ref={gauge} className={cx('dm-sbx-g', hot >= 0 && 'dm-hov')} role="meter" aria-label={title} aria-valuemin={0} aria-valuemax={100} aria-valuenow={total}
          aria-valuetext={`${total} of 100, ${band(total).toLowerCase()}${d === null ? '' : `, ${d >= 0 ? 'up' : 'down'} ${Math.abs(d)} ${since}`}`}>
          <svg viewBox="0 0 200 108" aria-hidden="true">
            {factors.map((f, i) => <Segment key={f.key} a0={seg[i][0]} a1={seg[i][1]} share={drawn ? f.earned / f.weight : 0} color={PAL[i % PAL.length]} on={i === hot} onPoint={o => setHot(o ? i : -1)} />)}
          </svg>
          <div className="dm-sbx-v"><b className="dm-num">{Math.round(shown)}</b><span className="dm-muted">of 100</span></div>
        </div>
        <div className="dm-sbx-s"><b>{title}</b>
          <span className="dm-sbx-band"><Swap className={cx('dm-muted', !drawn && 'dm-shim')}>{drawn ? band(total) : 'Scoring'}</Swap>{d !== null && drawn && <span className={cx('dm-tag dm-num', d >= 0 ? 'dm-ok' : 'dm-bad')}>{d >= 0 ? '+' : '−'}{Math.abs(d)} {since}</span>}</span>
        </div>
      </div>
      <div ref={listRef} className="dm-sbx-list" onPointerLeave={e => { if (!e.currentTarget.contains(document.activeElement)) setHot(-1); }} onBlur={e => { if (!e.currentTarget.contains(e.relatedTarget as Node)) setHot(-1); }}>
        {factors.map((f, i) => {
          const isOpen = opened.includes(f.key), lost = f.weight - f.earned, pr = props[f.key];
          return (
            <div key={f.key} className={cx('dm-sbx-r', i === hot && 'dm-on', isOpen && 'dm-open')} onPointerEnter={e => { if (e.pointerType !== 'touch') setHot(i); }} onFocus={() => setHot(i)}>
              <button type="button" className="dm-sbx-rh" aria-expanded={isOpen} aria-label={`${f.label}: ${f.earned} of ${f.weight} points${i === weakest ? ', weakest' : ''}. ${f.note}`}
                onClick={() => setOpened(isOpen ? opened.filter(k => k !== f.key) : [...opened, f.key])}>
                <i style={{ background: PAL[i % PAL.length] }} /><span className="dm-n"><span>{f.label}</span>{i === weakest && <span className="dm-tag dm-warn">Weakest</span>}</span>
                <span className="dm-e dm-num">{f.earned}/{f.weight}</span><span className="dm-bar"><i style={{ width: drawn ? f.earned / f.weight * 100 + '%' : 0 }} /></span>
                <Icon name="chev-r" size="xs" /><span className="dm-sbx-nt">{f.note}</span>
              </button>
              <Fold open={isOpen}>
                <Detail>
                  {pr === 'busy' ? <div className="dm-sbx-pr dm-enter"><span className="dm-k"><Icon name="spark" size="xs" /><span className="dm-shim">{improvingLabel}</span></span></div>
                    : pr ? <div className="dm-sbx-pr"><span className="dm-k"><Icon name="spark" size="xs" />Proposal</span><span>{pr.text}</span>
                        <span className="dm-gain">{pr.gain ? pr.gain + ': ' : ''}{f.label} <b className="dm-num">{f.earned} → {pr.to}</b></span>
                        <span className="dm-acts"><button type="button" className="dm-pill dm-primary dm-sm" onClick={() => { drop(f.key); onApply?.(f, pr); }}>Apply</button><button type="button" className="dm-pill dm-ghost dm-sm" onClick={() => drop(f.key)}>Not now</button></span></div>
                    : <><span>{f.detail ? f.detail + ' ' : ''}{lost ? `Loses ${lost} of its ${f.weight} points` : 'Full marks'}{i === weakest && lost ? ', the most of any factor for its weight.' : '.'}</span>
                        {f.improvable && onImprove && <span className="dm-acts"><button type="button" className="dm-pill dm-line dm-sm dm-sbx-imp" onClick={() => improve(f)}><Icon name="wand" size="xs" />Improve</button></span>}</>}
                </Detail>
              </Fold>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Score breakdown ---------- */
/* the gauge is split into one segment per factor, sized by its weight, each filled by the points it earned; the rows under it
   say what each earned and why, and the weakest one says so in words */
/* 16px in from every edge (owner, 18 Nov): the last row's 8px of hover room makes up the bottom. The rows reach 8px out round
   their words, so each row's colour key sits on the content's left edge; the first row is 16px under the hairline. A row's key is
   the gauge's colour for its part (the legend), and its bar is the accent on a neutral track, one colour for every row */
.dm-sbx{padding:var(--dm-s-4) var(--dm-s-4) var(--dm-s-2);display:flex;flex-direction:column;gap:var(--dm-s-4)}
.dm-sbx-top{display:flex;align-items:center;gap:var(--dm-s-4)}
.dm-sbx-g{position:relative;width:160px;height:88px;flex:none}
.dm-sbx-g svg{width:100%;height:100%;overflow:visible}
/* Soft's gauge has round ends (owner, 21 Nov: "Soft needs to have rounded corners for these lines, because it's Soft"): the script
   draws each part --dm-sbx-cap shorter at both ends, so its round caps keep the gaps between the parts. Blueprint and Clean draw
   square ends */
.dm-sbx-g{--dm-sbx-cap:8}
.dm-sbx-g path{fill:none;stroke-width:16;stroke-linecap:round;transition:opacity .3s}
:root:not([data-style="soft"],[data-style="clean"]) .dm-sbx-g:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){--dm-sbx-cap:0}
:root:not([data-style="soft"],[data-style="clean"]) .dm-sbx-g path:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){stroke-linecap:butt}
.dm-sbx-g .dm-tr{stroke:var(--dm-chip)}
.dm-sbx-g.dm-hov g:not(.dm-on) .dm-fl{opacity:.3}
.dm-sbx-g g{cursor:default}
.dm-sbx-v{position:absolute;left:0;right:0;bottom:0;display:flex;flex-direction:column;align-items:center;line-height:1.25}
.dm-sbx-v b{font-size:14px;font-weight:500}
.dm-sbx-v .dm-muted{font-size:11px}
.dm-sbx-s{display:flex;flex-direction:column;gap:2px;font-size:13.5px;min-width:0}
.dm-sbx-s b{font-weight:500}
.dm-sbx-band{display:flex;align-items:baseline;gap:var(--dm-s-2);flex-wrap:wrap;font-size:12.5px}
/* the change chip keeps its centred text when it crossfades (a swapped element is otherwise an inline block, which drops
   its text to the top), and shares a baseline with the band word beside it */
.dm-sbx-band .dm-tag{display:inline-flex}
.dm-sbx-list{display:flex;flex-direction:column;gap:2px;padding-top:var(--dm-s-2);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-sbx-r{margin:0 calc(-1 * var(--dm-s-2));border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease)}
.dm-sbx-r.dm-on,.dm-sbx-r.dm-open{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-sbx-r:hover{background:var(--dm-row)}}
.dm-sbx-rh{display:grid;grid-template-columns:8px minmax(0,1fr) auto 56px 12px;align-items:center;column-gap:10px;width:100%;padding:var(--dm-s-2);font-size:13px;text-align:left}
.dm-sbx-rh>i{width:8px;height:8px;border-radius:calc(2px * var(--dm-rk-s,var(--dm-rk)))}
.dm-sbx-rh .dm-n{display:flex;align-items:center;gap:6px;min-width:0}
.dm-sbx-rh .dm-n>span:first-child{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-sbx-rh .dm-tag{display:inline-flex;align-items:center;height:18px;padding-block:0;font-size:11px;line-height:1;flex:none}
.dm-sbx-rh:focus-visible{outline-offset:-2px;border-radius:inherit}
.dm-sbx-rh .dm-e{font-size:12px;color:var(--dm-fg2)}
.dm-sbx-rh .dm-bar{height:5px;border-radius:calc(3px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-chip);overflow:hidden;transition:background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-sbx-r:is(:hover,.dm-on,.dm-open) .dm-sbx-rh .dm-bar{background:var(--dm-surface)}}
.dm-sbx-rh .dm-bar i{display:block;height:100%;width:0;border-radius:inherit;background:var(--dm-accent-mark,var(--dm-accent));transition:width .8s var(--dm-ease)}
.dm-sbx-rh>svg{color:var(--dm-muted);transition:transform .35s var(--dm-ease)}
.dm-sbx-r.dm-open .dm-sbx-rh>svg{transform:rotate(90deg)}
.dm-sbx-nt{grid-column:2/-1;font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@media (hover:hover) and (pointer:fine){.dm-sbx-r:is(:hover,.dm-on,.dm-open) .dm-sbx-nt{color:var(--dm-fg2)}}
.dm-sbx-d{padding:0 var(--dm-s-2) var(--dm-s-2) calc(var(--dm-s-2) + 18px);display:flex;flex-direction:column;gap:var(--dm-s-2);font-size:12.5px;color:var(--dm-fg2);line-height:1.5}
.dm-sbx-d .dm-acts{display:flex;gap:6px;flex-wrap:wrap}
.dm-sbx-pr{display:flex;flex-direction:column;gap:6px;padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-sbx-pr .dm-k{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--dm-muted)}
.dm-sbx-pr .dm-k .dm-i{color:var(--dm-accent-fg,var(--dm-accent))}
.dm-sbx-pr .dm-gain{font-size:12px;color:var(--dm-fg2)}
.dm-sbx-pr .dm-gain b{font-weight:500;color:var(--dm-ok);white-space:nowrap}
/* on a phone the gauge sits over its title, and the rows drop their small bars */
.dm-sbx{container-type:inline-size}
@container (max-width:340px){.dm-sbx-top{flex-direction:column;gap:var(--dm-s-2)}.dm-sbx-s{align-items:center;text-align:center}.dm-sbx-band{justify-content:center}.dm-sbx-rh{grid-template-columns:8px minmax(0,1fr) auto 12px}.dm-sbx-rh .dm-bar{display:none}}
:root[data-style="clean"] .dm-sbx-pr .dm-k .dm-i,:root [data-style="clean"] .dm-sbx-pr .dm-k .dm-i,:root [data-style="clean"].dm-sbx-pr .dm-k .dm-i{color:var(--dm-fg2)}
/* Clean (owner, 21 Nov: Clean must differ from Soft). The gauge is thinner, with square ends and a neutral track; the factors sit
   under a hairline that runs the card's width, as Clean's sections do. Each factor is a 10px row under one gliding hover
   (hoverGlide), an open one taking the one selected fill; its key is a round dot, and its bar a sunk track (Clean's inner
   shadow over the fill). The agent's fix inside an open factor is an inset off-white note with 10px corners */
:root[data-style="clean"] .dm-sbx-g,:root [data-style="clean"] .dm-sbx-g,:root [data-style="clean"].dm-sbx-g{--dm-sbx-cap:0}
:root[data-style="clean"] .dm-sbx-g path,:root [data-style="clean"] .dm-sbx-g path,:root [data-style="clean"].dm-sbx-g path{stroke-width:12;stroke-linecap:butt}
:root[data-style="clean"] .dm-sbx-g .dm-tr,:root [data-style="clean"] .dm-sbx-g .dm-tr,:root [data-style="clean"].dm-sbx-g .dm-tr{stroke:var(--dm-soft)}
:root[data-style="clean"] .dm-sbx-list,:root [data-style="clean"] .dm-sbx-list,:root [data-style="clean"].dm-sbx-list{margin:0 -16px;padding:8px 16px 0;border-top:1px solid var(--dm-line)}
:root[data-style="clean"] .dm-sbx-r,:root [data-style="clean"] .dm-sbx-r,:root [data-style="clean"].dm-sbx-r{border-radius:10px}
:root[data-style="clean"] .dm-sbx-r.dm-open,:root [data-style="clean"] .dm-sbx-r.dm-open,:root [data-style="clean"].dm-sbx-r.dm-open{background:var(--dm-row-on)}
:root[data-style="clean"] .dm-sbx-rh>i,:root [data-style="clean"] .dm-sbx-rh>i,:root [data-style="clean"].dm-sbx-rh>i{border-radius:50%}
:root[data-style="clean"] .dm-sbx-rh .dm-bar,:root [data-style="clean"] .dm-sbx-rh .dm-bar,:root [data-style="clean"].dm-sbx-rh .dm-bar{position:relative;background:var(--dm-soft);border-radius:var(--dm-r-pill)}
:root[data-style="clean"] .dm-sbx-rh .dm-bar::after,:root [data-style="clean"] .dm-sbx-rh .dm-bar::after,:root [data-style="clean"].dm-sbx-rh .dm-bar::after{content:"";position:absolute;inset:0;border-radius:inherit;box-shadow:var(--dm-track-ring);pointer-events:none}
:root[data-style="clean"] .dm-sbx-pr,:root [data-style="clean"] .dm-sbx-pr,:root [data-style="clean"].dm-sbx-pr{background:var(--dm-strip);box-shadow:none;border-radius:10px}
/* in dark mode a track on a lit row takes the hover grey, so it still shows */
@media (hover:hover) and (pointer:fine){:root[data-theme="dark"] .dm-sbx-r:is(:hover,.dm-on,.dm-open) .dm-sbx-rh .dm-bar{background:var(--dm-hover)}}
@media (prefers-color-scheme:dark){@media (hover:hover) and (pointer:fine){:root:not([data-theme="light"]) .dm-sbx-r:is(:hover,.dm-on,.dm-open) .dm-sbx-rh .dm-bar{background:var(--dm-hover)}}}

